"""Command-line interface for jobwatch."""

from __future__ import annotations

import argparse
import sys
from datetime import datetime
from pathlib import Path

from . import __version__, db, reports
from .parser import MalformedRowError, parse_file

MALFORMED_FATAL_FRACTION = 0.10


def format_elapsed(seconds: int) -> str:
    """Render seconds as ``[D-]HH:MM:SS``."""
    days, rem = divmod(seconds, 86400)
    hours, rem = divmod(rem, 3600)
    minutes, secs = divmod(rem, 60)
    base = f"{hours:02d}:{minutes:02d}:{secs:02d}"
    return f"{days}-{base}" if days else base


def format_table(headers: list[str], rows: list[list[str]]) -> str:
    """Render a simple left-aligned fixed-width table."""
    widths = [len(h) for h in headers]
    for row in rows:
        for i, cell in enumerate(row):
            widths[i] = max(widths[i], len(cell))
    lines = [
        "  ".join(h.ljust(w) for h, w in zip(headers, widths)).rstrip(),
        "  ".join("-" * w for w in widths),
    ]
    for row in rows:
        lines.append("  ".join(c.ljust(w) for c, w in zip(row, widths)).rstrip())
    return "\n".join(lines)


def _validate_since(text: str) -> str:
    try:
        return datetime.fromisoformat(text).isoformat(sep="T")
    except ValueError:
        raise argparse.ArgumentTypeError(
            f"not an ISO date/datetime: {text!r}"
        ) from None


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="jobwatch",
        description="Snapshot Slurm sacct dumps into SQLite and render usage reports.",
    )
    parser.add_argument(
        "--version", action="version", version=f"%(prog)s {__version__}"
    )
    parser.add_argument(
        "--db",
        type=Path,
        default=db.DEFAULT_DB_PATH,
        help=f"path to the SQLite database (default: {db.DEFAULT_DB_PATH})",
    )
    sub = parser.add_subparsers(dest="command", required=True)

    p_ingest = sub.add_parser("ingest", help="ingest a pipe-delimited sacct dump")
    p_ingest.add_argument("file", type=Path, help="sacct dump file")

    p_report = sub.add_parser("report", help="render a report")
    report_sub = p_report.add_subparsers(dest="report_kind", required=True)

    p_usage = report_sub.add_parser(
        "usage", help="CPU/GPU-hours grouped by user or partition"
    )
    p_usage.add_argument("--since", type=_validate_since, required=True)
    p_usage.add_argument("--by", choices=("user", "partition"), default="user")

    p_failures = report_sub.add_parser(
        "failures", help="FAILED/TIMEOUT/OOM jobs and per-partition failure rates"
    )
    p_failures.add_argument("--since", type=_validate_since, required=True)

    p_top = sub.add_parser(
        "top", help="top users by GPU-hours over the trailing 7 days"
    )
    p_top.add_argument("--n", type=int, default=10, help="number of users to show")

    return parser


def cmd_ingest(args: argparse.Namespace) -> int:
    try:
        result = parse_file(args.file)
    except FileNotFoundError:
        print(f"error: no such file: {args.file}", file=sys.stderr)
        return 2
    except MalformedRowError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 2
    conn = db.connect(args.db)
    try:
        stats = db.upsert_jobs(conn, result.records)
    finally:
        conn.close()
    print(
        f"Ingested {len(result.records)} jobs from {args.file} "
        f"({stats.inserted} new, {stats.updated} updated, "
        f"{stats.unchanged} unchanged, {stats.stale_skipped} stale skipped; "
        f"{result.steps_skipped} step rows ignored, "
        f"{result.malformed} malformed rows skipped)"
    )
    if result.malformed_fraction > MALFORMED_FATAL_FRACTION:
        print(
            f"error: {result.malformed}/{result.total_rows} rows malformed "
            f"({result.malformed_fraction:.0%} > {MALFORMED_FATAL_FRACTION:.0%})",
            file=sys.stderr,
        )
        return 1
    return 0


def cmd_report_usage(args: argparse.Namespace) -> int:
    conn = db.connect(args.db)
    try:
        rows = reports.usage(conn, args.since, args.by)
    finally:
        conn.close()
    if not rows:
        print(f"No jobs since {args.since}.")
        return 0
    table = [
        [r.key, f"{r.cpu_hours:.2f}", f"{r.gpu_hours:.2f}", str(r.jobs)] for r in rows
    ]
    print(f"Usage since {args.since}, by {args.by}:")
    print(format_table([args.by.capitalize(), "CPU-hours", "GPU-hours", "Jobs"], table))
    return 0


def cmd_report_failures(args: argparse.Namespace) -> int:
    conn = db.connect(args.db)
    try:
        rows, rates = reports.failures(conn, args.since)
    finally:
        conn.close()
    if rows:
        table = [
            [
                r.job_id,
                r.user,
                r.partition,
                r.state,
                format_elapsed(r.elapsed_sec),
                r.exit_code,
            ]
            for r in rows
        ]
        print(f"Failures since {args.since}:")
        print(
            format_table(
                ["JobID", "User", "Partition", "State", "Elapsed", "ExitCode"], table
            )
        )
    else:
        print(f"No failures since {args.since}.")
    if rates:
        summary = ", ".join(
            f"{r.partition}: {r.failed}/{r.total} ({r.rate:.1%})" for r in rates
        )
        print(f"Failure rate per partition: {summary}")
    return 0


def cmd_top(args: argparse.Namespace) -> int:
    if args.n < 1:
        print("error: --n must be at least 1", file=sys.stderr)
        return 2
    conn = db.connect(args.db)
    try:
        rows, window_start = reports.top_users(conn, args.n)
    finally:
        conn.close()
    if window_start is None:
        print("Database is empty; nothing to report.")
        return 0
    print(f"Top {args.n} users by GPU-hours (trailing 7 days from {window_start}):")
    if not rows:
        print("No jobs in the trailing window.")
        return 0
    table = [
        [r.key, f"{r.gpu_hours:.2f}", f"{r.cpu_hours:.2f}", str(r.jobs)] for r in rows
    ]
    print(format_table(["User", "GPU-hours", "CPU-hours", "Jobs"], table))
    return 0


def main(argv: list[str] | None = None) -> int:
    args = build_parser().parse_args(argv)
    if args.command == "ingest":
        return cmd_ingest(args)
    if args.command == "report":
        if args.report_kind == "usage":
            return cmd_report_usage(args)
        return cmd_report_failures(args)
    return cmd_top(args)


if __name__ == "__main__":
    sys.exit(main())

"""Parsing of pipe-delimited sacct dumps.

Expected layout (header row required):

    JobID|User|Partition|State|Submit|Start|End|Elapsed|AllocCPUS|AllocTRES|ExitCode

Job steps (``12345.batch``, ``12345.0``, ``12345.extern``) are skipped — only
top-level jobs are recorded. Malformed rows are reported to stderr and
skipped; the caller decides whether the malformed fraction is fatal.
"""

from __future__ import annotations

import re
import sys
from dataclasses import dataclass
from datetime import datetime
from pathlib import Path

HEADER_FIELDS = [
    "JobID",
    "User",
    "Partition",
    "State",
    "Submit",
    "Start",
    "End",
    "Elapsed",
    "AllocCPUS",
    "AllocTRES",
    "ExitCode",
]

# sacct renders absent timestamps as one of these.
_MISSING_TIMESTAMPS = {"", "Unknown", "None", "N/A"}

_ELAPSED_RE = re.compile(r"^(?:(\d+)-)?(\d{1,2}):(\d{2}):(\d{2})$")


class MalformedRowError(ValueError):
    """Raised when a data row cannot be parsed."""


@dataclass(frozen=True)
class JobRecord:
    job_id: str
    user: str
    partition: str
    state: str
    submit: str | None  # ISO-8601 text or None
    start: str | None
    end: str | None
    elapsed_sec: int
    alloc_cpus: int
    gpus: int
    exit_code: str


@dataclass
class ParseResult:
    records: list[JobRecord]
    steps_skipped: int
    malformed: int
    total_rows: int  # data rows, excluding the header

    @property
    def malformed_fraction(self) -> float:
        if self.total_rows == 0:
            return 0.0
        return self.malformed / self.total_rows


def is_step(job_id: str) -> bool:
    """True for step rows such as ``12345.batch`` or ``12345.0``."""
    return "." in job_id


def parse_elapsed(text: str) -> int:
    """Convert ``[DD-]HH:MM:SS`` to seconds."""
    m = _ELAPSED_RE.match(text.strip())
    if not m:
        raise MalformedRowError(f"bad elapsed value: {text!r}")
    days, hours, minutes, seconds = m.groups()
    if int(minutes) > 59 or int(seconds) > 59:
        raise MalformedRowError(f"bad elapsed value: {text!r}")
    total = int(hours) * 3600 + int(minutes) * 60 + int(seconds)
    if days:
        total += int(days) * 86400
    return total


def parse_tres_gpus(text: str) -> int:
    """Extract the GPU count from an AllocTRES string.

    Handles plain (``gres/gpu=2``) and typed (``gres/gpu:a100=4``) entries;
    multiple GPU entries are summed. Other gres kinds (``gres/shard=8``,
    ``gres/gpumem=...``) are ignored. An empty string means no TRES.
    """
    text = text.strip()
    if not text:
        return 0
    total = 0
    for item in text.split(","):
        item = item.strip()
        if not item:
            continue
        key, sep, value = item.partition("=")
        if not sep:
            raise MalformedRowError(f"bad TRES entry: {item!r}")
        if key == "gres/gpu" or key.startswith("gres/gpu:"):
            try:
                total += int(value)
            except ValueError:
                raise MalformedRowError(f"bad GPU count in TRES: {item!r}") from None
    return total


def parse_timestamp(text: str) -> str | None:
    """Validate a sacct timestamp; return normalized ISO text or None."""
    text = text.strip()
    if text in _MISSING_TIMESTAMPS:
        return None
    try:
        return datetime.fromisoformat(text).isoformat(sep="T")
    except ValueError:
        raise MalformedRowError(f"bad timestamp: {text!r}") from None


def normalize_state(text: str) -> str:
    """Reduce states like ``CANCELLED by 1234`` to their first token."""
    state = text.strip().split()[0] if text.strip() else ""
    if not state:
        raise MalformedRowError("empty state")
    return state.upper()


def parse_row(fields: list[str]) -> JobRecord | None:
    """Parse one data row. Returns None for step rows."""
    if len(fields) != len(HEADER_FIELDS):
        raise MalformedRowError(
            f"expected {len(HEADER_FIELDS)} fields, got {len(fields)}"
        )
    job_id = fields[0].strip()
    if not job_id:
        raise MalformedRowError("empty JobID")
    if is_step(job_id):
        return None
    try:
        alloc_cpus = int(fields[8].strip())
    except ValueError:
        raise MalformedRowError(f"bad AllocCPUS: {fields[8]!r}") from None
    return JobRecord(
        job_id=job_id,
        user=fields[1].strip(),
        partition=fields[2].strip(),
        state=normalize_state(fields[3]),
        submit=parse_timestamp(fields[4]),
        start=parse_timestamp(fields[5]),
        end=parse_timestamp(fields[6]),
        elapsed_sec=parse_elapsed(fields[7]),
        alloc_cpus=alloc_cpus,
        gpus=parse_tres_gpus(fields[9]),
        exit_code=fields[10].strip(),
    )


def parse_file(path: str | Path, *, err=None) -> ParseResult:
    """Parse a sacct dump file, skipping steps and malformed rows."""
    if err is None:
        err = sys.stderr
    path = Path(path)
    records: list[JobRecord] = []
    steps_skipped = 0
    malformed = 0
    total_rows = 0
    with path.open(encoding="utf-8") as fh:
        header = fh.readline().rstrip("\n")
        if [f.strip() for f in header.split("|")] != HEADER_FIELDS:
            raise MalformedRowError(f"unrecognized header in {path}: {header!r}")
        for lineno, line in enumerate(fh, start=2):
            line = line.rstrip("\n")
            if not line.strip():
                continue
            total_rows += 1
            try:
                record = parse_row(line.split("|"))
            except MalformedRowError as exc:
                malformed += 1
                print(f"{path}:{lineno}: skipping malformed row: {exc}", file=err)
                continue
            if record is None:
                steps_skipped += 1
            else:
                records.append(record)
    return ParseResult(
        records=records,
        steps_skipped=steps_skipped,
        malformed=malformed,
        total_rows=total_rows,
    )

import io

import pytest

from jobwatch.parser import (
    HEADER_FIELDS,
    MalformedRowError,
    is_step,
    parse_elapsed,
    parse_file,
    parse_row,
    parse_timestamp,
    parse_tres_gpus,
)

from .conftest import CLEAN, MESSY


def make_fields(**overrides):
    base = {
        "JobID": "12345",
        "User": "alice",
        "Partition": "gpu",
        "State": "COMPLETED",
        "Submit": "2026-06-01T08:00:00",
        "Start": "2026-06-01T09:00:00",
        "End": "2026-06-01T10:00:00",
        "Elapsed": "01:00:00",
        "AllocCPUS": "8",
        "AllocTRES": "cpu=8,mem=64G,gres/gpu=2",
        "ExitCode": "0:0",
    }
    base.update(overrides)
    return [base[name] for name in HEADER_FIELDS]


class TestElapsed:
    def test_plain(self):
        assert parse_elapsed("01:30:00") == 5400

    def test_with_day_component(self):
        assert parse_elapsed("2-12:00:00") == 2 * 86400 + 12 * 3600

    def test_single_day(self):
        assert parse_elapsed("1-00:00:30") == 86400 + 30

    def test_zero(self):
        assert parse_elapsed("00:00:00") == 0

    @pytest.mark.parametrize("bad", ["12:99", "1:2", "", "garbage", "01:60:00", "-01:00:00"])
    def test_malformed(self, bad):
        with pytest.raises(MalformedRowError):
            parse_elapsed(bad)


class TestTres:
    def test_plain_gpu(self):
        assert parse_tres_gpus("cpu=8,mem=64G,gres/gpu=2") == 2

    def test_no_gpu(self):
        assert parse_tres_gpus("cpu=4,mem=16G") == 0

    def test_empty(self):
        assert parse_tres_gpus("") == 0

    def test_typed_gpu(self):
        assert parse_tres_gpus("cpu=8,mem=64G,gres/gpu:a100=4") == 4

    def test_multiple_gres_entries_only_counts_gpus(self):
        assert parse_tres_gpus("cpu=16,mem=128G,gres/gpu=2,gres/shard=8") == 2

    def test_plain_and_typed_gpus_are_summed(self):
        assert parse_tres_gpus("cpu=8,gres/gpu=1,gres/gpu:h100=2") == 3

    def test_gpu_prefix_lookalike_ignored(self):
        assert parse_tres_gpus("cpu=8,gres/gpumem=4G") == 0

    def test_bad_gpu_count(self):
        with pytest.raises(MalformedRowError):
            parse_tres_gpus("gres/gpu=two")


class TestTimestamps:
    def test_unknown_is_none(self):
        assert parse_timestamp("Unknown") is None

    def test_valid(self):
        assert parse_timestamp("2026-06-01T08:00:00") == "2026-06-01T08:00:00"

    def test_invalid(self):
        with pytest.raises(MalformedRowError):
            parse_timestamp("yesterday")


class TestStepFiltering:
    @pytest.mark.parametrize("jid", ["12345.batch", "12345.0", "12345.extern"])
    def test_is_step(self, jid):
        assert is_step(jid)

    def test_top_level_is_not_step(self):
        assert not is_step("12345")

    def test_parse_row_returns_none_for_steps(self):
        assert parse_row(make_fields(JobID="12345.batch")) is None

    def test_clean_fixture_steps_excluded(self):
        result = parse_file(CLEAN)
        assert result.steps_skipped == 6
        assert len(result.records) == 50
        assert all("." not in r.job_id for r in result.records)


class TestParseRow:
    def test_valid_row(self):
        rec = parse_row(make_fields())
        assert rec.job_id == "12345"
        assert rec.gpus == 2
        assert rec.elapsed_sec == 3600

    def test_wrong_field_count(self):
        with pytest.raises(MalformedRowError):
            parse_row(["12345", "alice", "gpu", "COMPLETED"])

    def test_bad_alloc_cpus(self):
        with pytest.raises(MalformedRowError):
            parse_row(make_fields(AllocCPUS="eight"))

    def test_cancelled_by_uid_normalized(self):
        rec = parse_row(make_fields(State="CANCELLED by 1234"))
        assert rec.state == "CANCELLED"


class TestParseFile:
    def test_messy_fixture_counts(self):
        err = io.StringIO()
        result = parse_file(MESSY, err=err)
        assert result.total_rows == 30
        assert result.malformed == 3
        assert result.malformed_fraction == pytest.approx(0.10)
        assert result.steps_skipped == 3
        assert len(result.records) == 24
        assert err.getvalue().count("skipping malformed row") == 3

    def test_messy_edge_records(self):
        records = {r.job_id: r for r in parse_file(MESSY, err=io.StringIO()).records}
        assert records["2001"].end is None  # RUNNING, End Unknown
        assert records["2002"].elapsed_sec == 2 * 86400 + 12 * 3600
        assert records["2003"].gpus == 0
        assert records["2004"].gpus == 2  # gres/shard ignored
        assert records["2005"].gpus == 4  # typed gres/gpu:a100
        assert records["2006"].gpus == 3  # plain + typed summed
        assert records["2007"].start is None and records["2007"].gpus == 0

    def test_bad_header_rejected(self, tmp_path):
        f = tmp_path / "bad.txt"
        f.write_text("Foo|Bar\n1|2\n")
        with pytest.raises(MalformedRowError):
            parse_file(f)
